import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void layernorm_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Gamma,
    const T* __restrict__ Beta,
    T* __restrict__ Y,
    int N, int M, float eps)
{
    constexpr int Threads = 256;

    int n   = blockIdx.x;
    int tid = threadIdx.x;

    if (n >= N) return;

    // CuTe tensors for this row and for the per-element affine params
    Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * M),
                             make_shape(M), make_stride(Int<1>{}));
    Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * M),
                             make_shape(M), make_stride(Int<1>{}));
    Tensor mGamma = make_tensor(make_gmem_ptr(Gamma),
                                 make_shape(M), make_stride(Int<1>{}));
    Tensor mBeta  = make_tensor(make_gmem_ptr(Beta),
                                 make_shape(M), make_stride(Int<1>{}));

    double sum   = 0.0;
    double sumsq = 0.0;

    for (int i = tid; i < M; i += Threads) {
        double v = static_cast<double>(mX(i));
        sum   += v;
        sumsq += v * v;
    }

    __shared__ double s_sum[Threads];
    __shared__ double s_sumsq[Threads];
    s_sum[tid]   = sum;
    s_sumsq[tid] = sumsq;
    __syncthreads();

    #pragma unroll
    for (int offset = Threads / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            s_sum[tid]   += s_sum[tid + offset];
            s_sumsq[tid] += s_sumsq[tid + offset];
        }
        __syncthreads();
    }

    __shared__ double mean_s;
    __shared__ double invstd_s;
    if (tid == 0) {
        double mean = s_sum[0] / (double)M;
        double var  = s_sumsq[0] / (double)M - mean * mean;
        if (var < 0.0) var = 0.0;
        double invstd = 1.0 / sqrt(var + (double)eps);
        mean_s   = mean;
        invstd_s = invstd;
    }
    __syncthreads();

    double mean   = mean_s;
    double invstd = invstd_s;

    for (int i = tid; i < M; i += Threads) {
        double v = static_cast<double>(mX(i));
        double g = static_cast<double>(mGamma(i));
        double b = static_cast<double>(mBeta(i));
        double out = (v - mean) * invstd * g + b;
        mY(i) = static_cast<T>(out);
    }
}

torch::Tensor cute_layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(gamma.is_cuda(), "gamma must be CUDA");
    TORCH_CHECK(beta.is_cuda(), "beta must be CUDA");

    auto x_c = x.contiguous();
    auto gamma_c = gamma.contiguous();
    auto beta_c = beta.contiguous();

    int64_t normalized_ndim = gamma_c.dim();
    int64_t M = 1;
    for (int64_t i = 0; i < normalized_ndim; ++i) {
        M *= gamma_c.size(i);
    }
    int64_t total = x_c.numel();
    TORCH_CHECK(total % M == 0, "input numel not divisible by normalized_shape numel");
    int64_t N = total / M;

    auto y = torch::empty_like(x_c);

    constexpr int Threads = 256;
    dim3 grid((unsigned)N);
    dim3 block(Threads);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    AT_DISPATCH_FLOATING_TYPES(x_c.scalar_type(), "cute_layernorm_forward", ([&] {
        layernorm_kernel<scalar_t><<<grid, block, 0, stream>>>(
            x_c.data_ptr<scalar_t>(),
            gamma_c.data_ptr<scalar_t>(),
            beta_c.data_ptr<scalar_t>(),
            y.data_ptr<scalar_t>(),
            (int)N, (int)M, (float)eps
        );
    }));

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single custom CUTE/CUDA kernel that fuses
    mean/variance computation and the affine normalization.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layernorm_forward(
            x, self.weight, self.bias, float(self.eps)
        )

